using System;
using System.Collections.Generic;
using System.DirectoryServices;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;

namespace PdfGen.Core
{
    public class FeatureFlags
    {
        public bool EnableWatermark { get; set; } = true;
        public bool EnableHeaderLookup { get; set; } = true;
        public bool UseDirectoryGroupResolution { get; set; } = true;
        public string LdapBaseDn { get; set; } = "DC=corp,DC=local";
        public string LdapServer { get; set; } = "ldap://dc01.corp.local";
    }

    public class PdfMetadata
    {
        public string Title { get; set; }
        public string Author { get; set; }
        public string Department { get; set; }
        public string Classification { get; set; }
    }

    public interface ILdapQueryBuilder
    {
        string BuildFilter(string attribute, string value);
    }

    public class SafeLdapQueryBuilder : ILdapQueryBuilder
    {
        private static readonly Dictionary<char, string> EscapeMap = new Dictionary<char, string>
        {
            {'\\', "\\5c"}, {'*', "\\2a"}, {'(', "\\28"},
            {')', "\\29"}, {'\0', "\\00"}, {'/', "\\2f"}
        };

        public string BuildFilter(string attribute, string value)
        {
            var sanitized = SanitizeLdapValue(value);
            return $"({attribute}={sanitized})";
        }

        private string SanitizeLdapValue(string input)
        {
            if (string.IsNullOrEmpty(input)) return string.Empty;
            var sb = new StringBuilder(input.Length);
            foreach (var c in input)
            {
                if (EscapeMap.TryGetValue(c, out var escaped))
                    sb.Append(escaped);
                else
                    sb.Append(c);
            }
            return sb.ToString();
        }
    }

    public class DirectoryGroupResolver
    {
        private readonly FeatureFlags _flags;
        private readonly ILdapQueryBuilder _queryBuilder;

        public DirectoryGroupResolver(FeatureFlags flags, ILdapQueryBuilder queryBuilder)
        {
            _flags = flags;
            _queryBuilder = queryBuilder;
        }

        public string ResolveUserDepartment(string username)
        {
            if (!_flags.UseDirectoryGroupResolution)
                return "Unknown";

            var filter = BuildUserFilter(username);
            return ExecuteLdapQuery(filter);
        }

        private string BuildUserFilter(string username)
        {
            // Apply sanitization before normalization
            var normalized = NormalizeUsername(username);
            return _queryBuilder.BuildFilter("sAMAccountName", normalized);
        }

        private string NormalizeUsername(string username)
        {
            // Strip domain prefix if present (DOMAIN\user -> user)
            if (username.Contains("\\"))
                username = username.Split('\\')[1];

            // Handle UPN format (user@domain -> user)
            if (username.Contains("@"))
                username = username.Split('@')[0];

            // Unicode normalization - decompose then recompose
            // This handles cases like accented characters
            username = username.Normalize(NormalizationForm.FormD);
            username = username.Normalize(NormalizationForm.FormC);

            return username;
        }

        private string ExecuteLdapQuery(string filter)
        {
            try
            {
                using (var entry = new DirectoryEntry(_flags.LdapServer + "/" + _flags.LdapBaseDn))
                using (var searcher = new DirectorySearcher(entry))
                {
                    searcher.Filter = filter;
                    searcher.PropertiesToLoad.Add("department");
                    var result = searcher.FindOne();
                    return result?.Properties["department"]?[0]?.ToString() ?? "Unknown";
                }
            }
            catch (Exception)
            {
                return "Unknown";
            }
        }
    }

    public class PdfDocumentGenerator
    {
        private readonly FeatureFlags _flags;
        private readonly DirectoryGroupResolver _resolver;

        public PdfDocumentGenerator(FeatureFlags flags, DirectoryGroupResolver resolver)
        {
            _flags = flags;
            _resolver = resolver;
        }

        public byte[] GenerateReport(string requestingUser, string content, PdfMetadata metadata)
        {
            if (_flags.EnableHeaderLookup)
            {
                metadata.Department = _resolver.ResolveUserDepartment(requestingUser);
            }

            metadata.Classification = DetermineClassification(metadata.Department);

            return RenderPdf(content, metadata);
        }

        private string DetermineClassification(string department)
        {
            var sensitive = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
            {
                "Finance", "Legal", "HR", "Executive"
            };
            return sensitive.Contains(department) ? "CONFIDENTIAL" : "INTERNAL";
        }

        private byte[] RenderPdf(string content, PdfMetadata metadata)
        {
            // Simplified PDF rendering
            var pdfContent = new StringBuilder();
            pdfContent.AppendLine("%PDF-1.4");
            pdfContent.AppendLine($"% Title: {metadata.Title}");
            pdfContent.AppendLine($"% Author: {metadata.Author}");
            pdfContent.AppendLine($"% Department: {metadata.Department}");
            pdfContent.AppendLine($"% Classification: {metadata.Classification}");
            if (_flags.EnableWatermark)
                pdfContent.AppendLine($"% Watermark: {metadata.Classification}");
            pdfContent.AppendLine(content);
            return Encoding.UTF8.GetBytes(pdfContent.ToString());
        }
    }
}
